import { Suspense } from "react";
import { headers } from "next/headers";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { clientIp } from "@/lib/rate-limit";
import { hashIp } from "@/lib/coupon-order";
import { firstMonthFreeEligible, firstMonthFreeEnabled, firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
import { getSettingBool } from "@/lib/settings";
import { annualDiscountPct } from "@/lib/annual-discount";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { VPS_TERMS, vpsTermPriceCents, termPriceCents, termDiscountPct } from "@/lib/billing-terms";
import { planIntroMonthlyCents } from "@/lib/intro-pricing";
import { regionsFrom, defaultRegionChoice, appSpriteKey, gameArt } from "@/lib/nx/catalog";
import { regionAvailability } from "@/lib/node-capacity";
import { regionForCountry, latencyCategory } from "@/lib/region-pick";
import { regionProbeUrls } from "@/lib/region-probe";
import { countryFromHeaders } from "@/lib/geo-currency";
import { countryFromRequestIp } from "@/lib/geo-ip";
import { GAME_DISPLAY, GAME_GENRES, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "@/lib/games";
import { GAME_CONFIG_SCHEMAS } from "@/lib/game-config";
import { GAME_FAMILIES } from "@/lib/games";
import { stripeConfigured } from "@/lib/stripe";
import { paypalConfigured } from "@/lib/paypal";
import { coinbaseConfigured } from "@/lib/coinbase-commerce";
import { customPlanCeiling, customPlanFloor, customPlanIntro, customPlanIntroPercent, customPlanRates, loadGameRateSettings, resolveGameFamilyRates, CustomPlanError } from "@/lib/custom-plan";
import { customPlanIntroTerms, gameCustomFloor } from "@/lib/custom-plan-pricing";
import { DeployView } from "@/components/nx/DeployView";
import type { CustomPlanConfig, GameCustomPlanConfig, AddonOption, EmailPlanOption, GameFamilyOption, HostingPlanOption, OsOption, PlanOption, TermOption } from "@/components/nx/order-types";

/* Data for the VPS deploy wizard.
 *
 * The one rule this file exists to keep: every number the wizard can display is
 * computed HERE, by the same functions that charge the card, and handed down
 * already worked out. The view prints; it never multiplies.
 *
 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
 * rate plus a discount percent. Sending the percent would mean the browser does
 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
 * when the customer decides. Terms are few and plans are few, so the matrix is
 * cheap and it cannot drift from `vpsTermPriceCents`.
 */

export const dynamic = "force-dynamic";

/* Icon per image, keyed off the platform's own `family` value rather than
   sniffing the display name. Control panels and applications have families too
   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
const ICON_BY_FAMILY: Record<string, string> = {
  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
  mysql: "mysql", postgres: "postgres", redis: "redis",
  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
};
function osIcon(family: string, category: string): string {
  return ICON_BY_FAMILY[family?.toLowerCase()]
    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
}

export default async function NxDeployPage() {
  const user = await requireUser();

  // Exit-intent 25%-off popup eligibility (Feature: EXIT25). "First-time
  // customer" is the codebase's own established predicate for exactly this
  // kind of gate — zero non-free `Server` rows — already enforced identically
  // by `firstTimeOnly` coupon checks in lib/order.ts and
  // lib/coupon-redemption.ts. Resolved HERE, server-side, and threaded down as
  // a plain boolean prop: the deploy page is already a server component
  // reading `user`, so there is no reason to let the client decide something
  // this consequential on its own.
  const [isFirstTimeCustomer, exitIntentEnabled] = await Promise.all([
    db.server.count({ where: { userId: user.id, isFree: false } }).then((n) => n === 0),
    getSettingBool("exit_intent_enabled", true),
  ]);

  // Real, per-customer eligibility for the first-month-free hosting promo —
  // NOT a display detail, the exact same advisory pre-check
  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
  // wizard's hosting/email price was a flat, precomputed matrix with zero
  // per-user awareness (deliberately: "so there is no round-trip to make"),
  // which is why the promo's own plan-card badge ("First month free") and
  // the wizard's actual total disagreed — the matrix could not have known
  // whether THIS customer still qualifies. One extra check here, resolved
  // alongside the rest of this page's own data fetching.
  const hdrs = await headers();
  const hostingPromoIpHash = hashIp(clientIp(hdrs), process.env.AUTH_SECRET ?? "nxeon") || null;
  // Same "real signal, real fallback" resolution the display-currency path
  // already uses (lib/currency-display.ts) — a CDN/proxy country header first,
  // else the bundled geoip-lite dataset off the client IP, "" (falsy) if
  // neither resolves. Feeds `defaultRegionKey` below so a fresh order seeds
  // the region actually closest to this visitor rather than an arbitrary one.
  const visitorCountry = countryFromHeaders(hdrs) || countryFromRequestIp(hdrs) || null;
  const hostingPromoEligible =
    firstMonthFreeAppliesTo("HOSTING") &&
    (await firstMonthFreeEnabled()) &&
    (await firstMonthFreeEligible(user.id, hostingPromoIpHash));

  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
    /* All three categories — the design's Server settings panel has a tab per
       category (Operating system / Control panels / Applications), which is
       exactly what ImageCategory already distinguishes. They are separated in
       the VIEW, not filtered out here: a game-server image is a real thing you
       can deploy, it just is not an answer to "pick an operating system". */
    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
       images, but Nxeon sells game servers as their own product with their own
       plans, panel and pricing — offering "Minecraft Server" as a VPS
       application sells the same thing twice, at the wrong price, without the
       game panel. Identified by `family` against the platform's own
       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
    db.osTemplate.findMany({
      where: { active: true, NOT: { family: { in: [...GAME_FAMILIES] } } },
      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    }),
    // enabled only — a disabled node is not a place we can provision. `orderBy`
    // makes this deterministic: without one, Postgres may return rows in any
    // order, and `regionsFrom` used to build the region picker straight off
    // that order — so "region #0", the default a fresh order seeded, could
    // silently change between requests. `regionsFrom` now sorts its own
    // output too (belt and suspenders), but the query itself should not rely
    // on incidental ordering either.
    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true, isPrimary: true }, orderBy: { id: "asc" } }),
    // "from" prices for the service tiles — the cheapest live plan of each kind,
    // read from the same tables the order path prices against.
    // Every active tier: the wizard groups them into families itself, so one
    // query serves both the "from" price on the tiles and the tier picker.
    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    annualDiscountPct(),
    extraDiskPerGbCents(),
    dedicatedIpMonthlyCents(),
    backupPlusMonthlyCents(),
  ]);

  /* "Build a custom server" — floor (today's top active plan), admin ceiling and
     per-unit rates, resolved by the SAME functions quoteCustomPlanAction and
     createCustomPlan re-validate against (lib/custom-plan.ts), so the sliders'
     bounds and preview price can never disagree with what the server accepts.
     Best-effort, exactly as the legacy wizard did it: the only way this throws
     is a catalogue with no active base plan, and then the custom option is
     simply hidden rather than the whole deploy page crashing. */
  let customPlan: CustomPlanConfig | null = null;
  // Reused below to build each GAME family's OWN custom-plan config
  // (gameCustomFloor + that family's own rate) — `null` (no VPS floor at all)
  // means every custom option, VPS and game alike, degrades the same way.
  let vpsFloorForGames: Awaited<ReturnType<typeof customPlanFloor>> | null = null;
  let vpsCeilingForGames: Awaited<ReturnType<typeof customPlanCeiling>> | null = null;
  try {
    // `intro`: the first-term discount terms for a custom VPS build, from the
    // same customPlanIntro() customPlanQuote prices with.
    const [floor, ceiling, rates, intro] = await Promise.all([
      customPlanFloor(), customPlanCeiling(), customPlanRates(), customPlanIntro(),
    ]);
    customPlan = { floor, ceiling, rates, intro };
    vpsFloorForGames = floor;
    vpsCeilingForGames = ceiling;
  } catch (e) {
    if (!(e instanceof CustomPlanError)) throw e;
  }
  // Read once (not once per family) — see loadGameRateSettings's own doc.
  const [gameRateSettings, customIntroPct] = vpsFloorForGames
    ? await Promise.all([loadGameRateSettings(), customPlanIntroPercent()])
    : [null, 0];

  /* The monthly term is the reference rate the cards show by default; the wizard
     re-reads this matrix when the customer changes term. Priced through
     `vpsTermPriceCents`, the same helper `orderQuote` uses. */
  const priceMatrix: Record<string, Record<number, number>> = {};
  for (const p of plans) {
    priceMatrix[p.id] = {};
    for (const t of VPS_TERMS) {
      // term total / months = the effective monthly rate at that term
      priceMatrix[p.id][t.months] = Math.round(
        vpsTermPriceCents(p.priceCents, t.months, annualPct) / t.months
      );
    }
  }

  /* "Recommended" is the middle of the ladder, not the most expensive — the
     default has to be a defensible choice, not an upsell. */
  const recommendedId = plans.length ? plans[Math.floor((plans.length - 1) / 2)].id : null;

  const planOptions: PlanOption[] = plans.map((p) => ({
    id: p.id,
    slug: p.slug,
    name: p.name,
    cpuCores: p.cpuCores,
    ramMB: p.ramMB,
    diskGB: p.diskGB,
    bandwidthTB: p.bandwidthTB,
    monthlyCents: p.priceCents,
    effectiveMonthlyCents: priceMatrix[p.id][1],
    // Through the SAME validator the charge path uses (lib/intro-pricing.ts),
    // not the raw column: a malformed/equal/higher intro value is ignored by
    // lib/order.ts, so the card must not headline it either. Game tiers below
    // already read it this way.
    introMonthlyCents: planIntroMonthlyCents(p),
    introRenewalMonthlyCents: planIntroMonthlyCents(p) !== null ? p.priceCents : null,
    recommended: p.id === recommendedId,
  }));

  const osOptions: OsOption[] = oses.map((o) => ({
    id: o.id,
    name: o.name,
    version: o.version ?? "",
    icon: osIcon(o.family, o.category),
    category: o.category,
    family: o.family,
    spriteKey: o.category === "PLAIN_OS" ? null : appSpriteKey(o.name),
  }));

  const termOptions: TermOption[] = VPS_TERMS.map((t) => ({
    months: t.months,
    label: t.label,
    discountPercent: termDiscountPct(t.months, annualPct),
  }));

  /* Add-on rates come from the same functions the charge path reads. A rate
     hardcoded next to a checkbox is how a display price and a charged price
     drift apart. */
  /* Families are built from the tiers that actually exist. A family with no
     active plan is not offered — the alternative is a card that leads to an
     empty tier list. Variants and the subdomain requirement come from the
     platform's own family schema, not from a list kept here. */
  // Leads the game grid, in this order, each badged "Popular" — the owner's
  // pick, not a computed ranking (no real play-count/order-volume signal
  // exists yet to rank by). `projectzomboid`/`sdtd` are the actual family
  // keys behind "Project Zomboid" / "7 Days to Die" (lib/games.ts
  // GAME_FAMILIES) — the display names aren't the lookup keys.
  const POPULAR_GAME_ORDER = ["minecraft", "rust", "valheim", "palworld", "projectzomboid", "terraria"];
  const gameFamilies: GameFamilyOption[] = (() => {
    const byFamily = new Map<string, typeof gamePlans>();
    for (const gp of gamePlans) {
      const list = byFamily.get(gp.gameFamily) ?? [];
      list.push(gp);
      byFamily.set(gp.gameFamily, list);
    }
    return [...byFamily.entries()].map(([family, tiers]) => {
      const schema = GAME_CONFIG_SCHEMAS[family];
      return {
        family,
        name: GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family,
        art: gameArt(family),
        variants: schema?.variants ?? [],
        defaultVariant: schema?.defaultVariant ?? "",
        genres: GAME_GENRES[family as keyof typeof GAME_GENRES] ?? [],
        /* Same source of truth quoteGameOrder (lib/game-order.ts) charges
           through — a second, hand-maintained "just minecraft" check here
           silently left every other hostname-connect family (ARK, the
           Source-engine titles, Satisfactory, Conan, 7 Days to Die,
           Enshrouded, and more) without a "Play address" field to fill in,
           so their orders could reach the payment step with no subdomain
           and no way to price. */
        needsSubdomain: family === "minecraft" || family === "bedrock"
          || HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily),
        /* Same lesson as needsSubdomain right above: a family's checkout-time
           required fields were never surfaced to the wizard at all, so an
           order for Valheim, CS2, Dragonwilds, Sunkenland, DST or Mordhau
           could reach Payment priced against an empty config and fail there
           with no field to fix it.
           NOT filtered by `field.phase` — that axis means "does changing this
           LATER need a redeploy" (FieldPhase is "deploy" | "live"), which has
           nothing to do with whether checkout should ask for it. Every field
           rides along here; the wizard shows `required` ones inline and folds
           the rest under a collapsed "Advanced settings" disclosure, since
           they all carry sensible defaults and are just as editable from the
           dashboard's Settings tab after purchase. */
        checkoutFields: schema?.fields ?? [],
        // Lead with the intro rate where one exists, same as every other
        // "from $X" price on this page — a tier's regular priceCents is its
        // RENEWAL rate post-grandfather-program, not what a new order pays.
        fromCents: Math.min(...tiers.map((t) => planIntroMonthlyCents(t) ?? t.priceCents)),
        popular: POPULAR_GAME_ORDER.includes(family),
        tiers: tiers.map((t) => ({
          id: t.id,
          name: t.name,
          ramMB: t.ramMB,
          cpuCores: t.cpuCores,
          diskGB: t.diskGB,
          slots: t.slots ?? null,
          monthlyCents: t.priceCents,
          termMonths: t.termMonths,
          // Same GRANDFATHER PROGRAM columns as Plan (lib/game-order.ts already
          // reads them at charge time) — `planIntroMonthlyCents` is generic
          // over any `{priceCents}` row, so this is the identical helper VPS
          // uses, not a second formula.
          introMonthlyCents: planIntroMonthlyCents(t),
          introRenewalMonthlyCents: planIntroMonthlyCents(t) !== null ? t.priceCents : null,
        })),
        // THIS family's own custom-build config — see order-types.ts's doc on
        // GameFamilyOption.customPlan for why it's not the shared `customPlan`
        // above (and why it carries `anchor`/`vpsFloorPriceCents` alongside
        // `floor`). `tiers` here is already `active: true` only (the query at
        // the top of this file), so the max-priceCents tier is a genuine
        // premade top tier, never a leftover custom one-off (those are always
        // created `active: false`).
        customPlan: ((): GameCustomPlanConfig | null => {
          if (!vpsFloorForGames || !vpsCeilingForGames || !gameRateSettings) return null;
          const topTier = tiers.reduce((max, t) => (t.priceCents > max.priceCents ? t : max));
          const anchor = { cpuCores: topTier.cpuCores, ramMB: topTier.ramMB, diskGB: topTier.diskGB, priceCents: topTier.priceCents };
          const floor = gameCustomFloor(vpsFloorForGames, anchor);
          const { rates } = resolveGameFamilyRates(family, gameRateSettings);
          // Anti-undercut floor from this family's own top tier's first-term
          // price, exactly as customGamePlanQuote builds it.
          const intro = customPlanIntroTerms(planIntroMonthlyCents(topTier) ?? topTier.priceCents, customIntroPct);
          return { floor, ceiling: vpsCeilingForGames, rates, anchor, vpsFloorPriceCents: vpsFloorForGames.priceCents, intro };
        })(),
      };
    }).sort((a, b) => {
      const pa = POPULAR_GAME_ORDER.indexOf(a.family);
      const pb = POPULAR_GAME_ORDER.indexOf(b.family);
      if (pa !== -1 || pb !== -1) return (pa === -1 ? 999 : pa) - (pb === -1 ? 999 : pb);
      return a.name.localeCompare(b.name);
    });
  })();

  const hostingOptions: HostingPlanOption[] = hostingPlans.map((h) => ({
    id: h.id, name: h.name, tagline: h.tagline,
    diskGB: h.diskGB, maxSites: h.maxSites, maxDatabases: h.maxDatabases,
    bandwidthTB: h.bandwidthTB, mailboxes: h.mailboxes,
    freeMigration: h.freeMigration, featured: h.featured,
    monthlyCents: h.priceCents,
  }));

  const emailOptions: EmailPlanOption[] = emailPlans.map((e) => ({
    id: e.id, name: e.name, mailboxes: e.mailboxes,
    storageGB: e.storageGB, monthlyCents: e.priceCents, termMonths: e.termMonths,
  }));

  /* Hosting and email price through `termPriceCents` — the same helper their
     own charge paths use (lib/actions-hosting.ts, lib/actions-email-hosting.ts).
     Built as a matrix for the same reason as the VPS one: sending a rate and a
     discount percent would put the multiply back in the browser. */
  const hostingMatrix: Record<string, Record<number, number>> = {};
  // The real term total — `termPriceCents` unrounded-and-redivided — for the
  // checkout math. hostingMatrix above rounds THIS down to a per-month rate
  // for display ("$X/mo" labels), which is a real, separate rounding step:
  // re-multiplying that rounded rate back up by the term (as the checkout
  // total once did) silently drifts a cent or two from what the charge path
  // (lib/actions-hosting.ts's hostingChargeCents, same termPriceCents call)
  // actually bills. One rounding, at the total, shared with the charge path.
  const hostingTotalMatrix: Record<string, Record<number, number>> = {};
  // One month of the plan's own rate, credited when this customer still
  // qualifies — same shape as the VPS quote's `regularPlanCents - plan.priceCents`
  // (lib/order.ts), just carried alongside the matrix instead of computed by
  // a server round-trip. 0 (no credit) once first_month_free is off, already
  // claimed on this account/IP, or the plan changes and this needs recomputing.
  const hostingFirstMonthFreeCents: Record<string, number> = {};
  for (const h of hostingPlans) {
    hostingMatrix[h.id] = {};
    hostingTotalMatrix[h.id] = {};
    for (const t of VPS_TERMS) {
      const totalCents = termPriceCents(h.priceCents, t.months, annualPct);
      hostingTotalMatrix[h.id][t.months] = totalCents;
      hostingMatrix[h.id][t.months] = Math.round(totalCents / t.months);
    }
    hostingFirstMonthFreeCents[h.id] = hostingPromoEligible ? h.priceCents : 0;
  }
  const emailMatrix: Record<string, Record<number, number>> = {};
  const emailTotalMatrix: Record<string, Record<number, number>> = {};
  for (const e of emailPlans) {
    emailMatrix[e.id] = {};
    emailTotalMatrix[e.id] = {};
    for (const t of VPS_TERMS) {
      const totalCents = termPriceCents(e.priceCents, t.months, annualPct);
      emailTotalMatrix[e.id][t.months] = totalCents;
      emailMatrix[e.id][t.months] = Math.round(totalCents / t.months);
    }
  }

  const addonOptions: AddonOption[] = [
    { key: "backup", name: "Backup Plus", note: "Longer retention, more restore points", icon: "archive", monthlyCents: backupCents, free: false },
    { key: "ip", name: "Dedicated IP", note: "An address of your own", icon: "nodes", monthlyCents: ipCents, free: false },
    { key: "malware", name: "Malware scanning", note: "Scheduled scans and alerts", icon: "shieldcheck", monthlyCents: 0, free: true },
    { key: "docker", name: "Docker pre-installed", note: "Ready for containers on first boot", icon: "docker", monthlyCents: 0, free: true },
  ];

  // Only regions where a Node actually exists — the wizard can never sell a
  // location we cannot provision in. Computed once so the picker's list and
  // the resolved default agree on the exact same (deterministically-ordered)
  // set — see lib/nx/catalog.ts.
  // Each region also carries the URL (if any) the visitor's browser times a
  // real round trip to for the card's "38 ms" — see lib/region-probe.ts. A
  // region with no reachable endpoint gets null and shows "— ms", never a
  // made-up figure.
  const probes = regionProbeUrls(nodes);
  // Live availability per region from the SAME strict scheduler that places the
  // order (lib/node-capacity.ts regionAvailability), sized for the smallest
  // active plan — so "Sold out" here means the order would really be refused —
  // and a coarse latency category relative to the visitor's geographic home region.
  const availability = await regionAvailability(plans[0]?.ramMB ?? gamePlans[0]?.ramMB ?? 1024).catch(() => ({} as Record<string, "available" | "limited" | "sold_out">));
  const visitorHome = regionForCountry(visitorCountry).region;
  const regions = regionsFrom(nodes).map((r) => ({
    ...r,
    probeUrl: probes[r.key] ?? null,
    availability: availability[r.key],
    latency: latencyCategory(visitorHome, r.key),
  }));
  const regionChoice = defaultRegionChoice(regions, visitorCountry);

  return (
    // OrderProvider (components/nx/order.tsx) reads a marketing Deploy button's
    // selection off the URL via `useSearchParams()` (see lib/deploy-intent.ts) —
    // Next.js requires a Suspense boundary around any client component that
    // calls it, same as the old wizard's DeployHub did (see
    // app/dashboard/deploy/legacy-page.tsx.bak).
    <Suspense fallback={<div className="h-64 animate-pulse rounded-3xl border border-white/[0.06] bg-navy-900/40" />}>
    <DeployView
      cat={{
        plans: planOptions,
        games: gameFamilies,
        hosting: hostingOptions,
        email: emailOptions,
        hostingMatrix,
        hostingTotalMatrix,
        hostingFirstMonthFreeCents,
        emailMatrix,
        emailTotalMatrix,
        oses: osOptions,
        terms: termOptions,
        addons: addonOptions,
        regions,
        // Resolved server-side — see lib/nx/catalog.ts's defaultRegionKey doc
        // comment for why this is no longer `regions[0]`.
        defaultRegionKey: regionChoice.region,
        defaultRegionSource: regionChoice.source,
        defaultRegionNote: regionChoice.note,
        diskPerGbCents,
        walletCents: user.balanceCents,
        customPlan,
      }}
      priceMatrix={priceMatrix}
      hostingMatrix={hostingMatrix}
      emailMatrix={emailMatrix}
      firstName={user.name.split(" ")[0]}
      /* Which payment methods to OFFER. Read from the same predicates the
         charge paths use, so a method is never shown unless the platform can
         actually take money through it. In this sandbox all three are false by
         design, which is why the wallet is the only way to pay here. */
      methods={{
        card: stripeConfigured(),
        paypal: paypalConfigured(),
        crypto: coinbaseConfigured(),
      }}
      /* PayPal's PUBLIC client id. Safe to send to the browser — it is what the
         PayPal SDK script is keyed on and appears in every PayPal integration's
         page source. The SECRET stays on the server, where `createPayPalOrder`
         uses it. Null unless PayPal is actually configured, so the wizard can
         never mount the SDK against an empty id. */
      paypalClientId={paypalConfigured() ? process.env.PAYPAL_CLIENT_ID ?? null : null}
      isFirstTimeCustomer={isFirstTimeCustomer}
      exitIntentEnabled={exitIntentEnabled}
      fromCents={{
        // Same rule as every other "from $X" price on this page: lead with
        // the intro rate where one exists, not the post-grandfather-program
        // renewal rate — this tile is the first thing a new customer sees,
        // and it was still showing the higher number.
        vps: plans.length ? Math.min(...plans.map((p) => planIntroMonthlyCents(p) ?? p.priceCents)) : null,
        game: gamePlans.length ? Math.min(...gamePlans.map((g) => planIntroMonthlyCents(g) ?? g.priceCents)) : null,
        hosting: hostingPlans.length ? Math.min(...hostingPlans.map((h) => h.priceCents)) : null,
        email: emailPlans.length ? Math.min(...emailPlans.map((e) => e.priceCents)) : null,
        // No fixed plan row for domains — real price is a live per-TLD
        // registrar quote. 999 ($9.99) used to stand in here as a flat
        // guess; `null` renders this tile's existing "Pricing unavailable"
        // fallback instead of a number that isn't real.
        domains: null,
      }}
    />
    </Suspense>
  );
}
