"use client";

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "next/navigation";
import { quoteOrder, type QuotedPrice } from "@/lib/nx/quote";
import { quoteGameOrder } from "@/lib/nx/quote-game";
import { quoteHostingOrder } from "@/lib/nx/quote-hosting";
import { quoteEmailOrder } from "@/lib/nx/quote-email";
import type { AddonOption, CartPrice, CustomPlanConfig, EmailPlanOption, GameFamilyOption, GameTier, HostingPlanOption, OsOption, PlanOption, TermOption } from "./order-types";
import type { Region } from "@/lib/nx/catalog";
import { DEPLOY_PARAM, type DeployIntent, type DeployService } from "@/lib/deploy-intent";
import { fieldRuleError, suggestedDefaults } from "@/lib/game-field-rules";
import { genDefaultVpsHostname } from "@/lib/hostname-shared";
import { checkHostnameAvailable } from "@/lib/actions-hostname-check";

/* Order state for the deploy wizard.
 *
 * Ported from the design sandbox with ONE structural change, and it is the
 * important one: the sandbox derived every money figure here in the browser
 * (`dueToday`, `saved`, `walletApplied`, `cardDue`) from a fixture price table.
 * None of that survives. The server is asked what the selection costs, and this
 * context only holds the answer. A price the browser works out is a second
 * pricing formula, and the first time it disagrees with `orderQuote` a customer
 * is shown one number and charged another.
 *
 * Kept exactly as designed:
 *  - Choosing a service seeds a COMPLETE, working configuration, so the order is
 *    buyable without touching anything. Only free defaults are pre-set; nothing
 *    that adds to the total is ever ticked for you.
 *  - Once a service is picked nothing is gated — you can commit from anywhere.
 *  - This is deliberately NOT a <form>. On the live platform an unkeyed ternary
 *    once made Continue and Deploy the same DOM node and charged five customers
 *    four steps early. The commit action is its own button and nothing else can
 *    submit.
 */

export type ServiceKey = "vps" | "game" | "hosting" | "email" | "domains";

export type Order = {
  service: ServiceKey | null;
  planId: string | null;
  termMonths: number;
  region: string | null;
  /** True once the customer clicked a region themselves (audit: "explicit" vs the preselected geo/default). */
  regionPicked?: boolean;
  osId: string | null;
  hostname: string;
  addons: string[];
  diskGb: number;
  couponCode: string;
  useWallet: boolean;
  launched: boolean;

  /* ── game ── */
  /** Family the customer picked; the tier below is what they actually buy. */
  gameFamily: string | null;
  gamePlanId: string | null;
  gameVariant: string | null;
  /** Minecraft only — `<subdomain>.play.nxeon.cloud`. */
  subdomain: string;
  serverName: string;
  /**
   * Raw values for the selected game's `phase: "deploy"` config fields (e.g.
   * Valheim's SERVER_PASS) — validated + coerced server-side against the
   * family schema (lib/game-config.ts) in gameOrderQuote/placeGameOrder.
   * Found live 2026-09-15: this bucket never existed, so a required deploy
   * field (Valheim, CS2, Dragonwilds, Sunkenland, DST, Mordhau) always failed
   * checkout with no field ever shown to fix it — the wizard priced against
   * an empty config no matter what the customer did on the Server step.
   */
  gameConfig: Record<string, string>;

  /* ── hosting & email ── */
  hostingPlanId: string | null;
  emailPlanId: string | null;
  /** The domain the account or mailboxes are bought FOR. */
  domain: string;
  /** Shared hosting: an nxeon subdomain instead of bringing your own name. */
  subdomainLabel: string;

  /* ── domains ── */
  /** The exact name being registered, chosen from a search result. */
  domainName: string;
  domainPriceCents: number | null;
  years: number;
  /** Registrant contact. A domain is registered in a REAL person's name and
      these details go to the registry, so they are part of the order, not a
      profile setting to be filled in later. */
  contact: {
    firstName: string; lastName: string; address1: string; city: string;
    stateProvince: string; postalCode: string; country: string; phone: string; email: string;
  };
};

const EMPTY: Order = {
  service: null, planId: null, termMonths: 1, region: null, osId: null,
  hostname: "", addons: [], diskGb: 0, couponCode: "",
  /* OFF by default. On means the balance silently pays and the customer never
     sees a card field — fine for a returning account with credit, confusing for
     everyone else. They opt IN to spending their balance. */
  useWallet: false, launched: false,
  gameFamily: null, gamePlanId: null, gameVariant: null, subdomain: "", serverName: "", gameConfig: {},
  domain: "", subdomainLabel: "", hostingPlanId: null, emailPlanId: null,
  domainName: "", domainPriceCents: null, years: 1,
  contact: { firstName: "", lastName: "", address1: "", city: "",
             stateProvince: "", postalCode: "", country: "", phone: "", email: "" },
};

export type Section = { key: string; label: string; done: boolean; live: boolean };

/** Status of a live "is this name available" round trip — shared shape with
 *  gameSubCheck/hostSubCheck (components/nx/DeployView.tsx). */
export type AvailabilityCheck = { status: "idle" | "checking" | "ok" | "bad"; reason?: string };

export type Catalog = {
  plans: PlanOption[];
  /** Empty when the platform has no active game plans. */
  games: GameFamilyOption[];
  hosting: HostingPlanOption[];
  email: EmailPlanOption[];
  /* Plan x term effective monthly rates, computed server-side. Display only
     (the "$X/mo" labels) — rounded once already, so never re-multiply this
     back up by the term for a total; use the *TotalMatrix below instead. */
  hostingMatrix: Record<string, Record<number, number>>;
  /* Plan x term real charge totals (termPriceCents, unrounded until this one
     step) — the same number lib/actions-hosting.ts's hostingChargeCents
     charges. This is what checkout math reads. */
  hostingTotalMatrix: Record<string, Record<number, number>>;
  /* One month of THIS plan's rate, credited only if the signed-in customer
     still qualifies for first-month-free hosting — resolved server-side
     per-request (lib/promo-redemption.ts), since the flat matrix above has
     no per-customer awareness by design. 0 = no credit (promo off, or
     already claimed on this account/IP). */
  hostingFirstMonthFreeCents: Record<string, number>;
  emailMatrix: Record<string, Record<number, number>>;
  emailTotalMatrix: Record<string, Record<number, number>>;
  oses: OsOption[];
  terms: TermOption[];
  addons: AddonOption[];
  regions: Region[];

  regions: Region[];
  /** The region a fresh VPS/game order should seed — resolved server-side by
   *  lib/nx/catalog.ts's `defaultRegionKey` (closest-to-visitor via geoip,
   *  falling back to a fixed default), never `regions[0]` — see seedOrder
   *  below for why that used to hand out a random region. Null only when the
   *  platform has no regions at all. */
  defaultRegionKey: string | null;
  /** How the preselected region was decided: "geo" (visitor's country known) or "default". */
  defaultRegionSource?: "geo" | "default";
  /** Honest note shown on the region step when the geo region was full and the preselection moved. */
  defaultRegionNote?: string | null;
  diskPerGbCents: number;
  walletCents: number;
  /** "Build a custom server" bounds + rates, or null when the platform has no
   *  base plan to anchor a custom spec to (the custom option is then hidden). */
  customPlan: CustomPlanConfig | null;
};

type Ctx = {
  o: Order;
  set: <K extends keyof Order>(k: K, v: Order[K]) => void;
  chooseService: (k: ServiceKey) => void;
  chooseGame: (family: string) => void;
  game: GameFamilyOption | null;
  toggleAddon: (k: string) => void;
  reset: () => void;
  cat: Catalog;
  plan: PlanOption | null;
  /* server-priced */
  price: CartPrice;
  pricing: boolean;
  priceError: string | null;
  walletApplied: number;
  cardDue: number;
  sections: Section[];
  activeIdx: number;
  /** Live VPS-hostname availability — see the debounced effect below and
   *  lib/actions-hostname-check.ts. Idle for every non-VPS service. */
  hostCheck: AvailabilityCheck;
  /** Make a just-created one-off custom plan (VPS) / tier (game) part of this
   *  session's catalogue and select it. The row already exists server-side
   *  (confirmCustom*Action), so from here it is bought through the exact same
   *  quote + payAndDeploy/payAndDeployGame path as any catalogue plan. */
  applyCustomPlan: (p: PlanOption) => void;
  applyCustomTier: (family: string, t: GameTier) => void;
};

/**
 * The full seed for a freshly-chosen service — same defaults `chooseService`
 * has always set (a complete, immediately-priceable order with only free
 * defaults ticked), pulled out as a pure function so `orderFromIntent` below
 * can start from the identical baseline before layering a marketing button's
 * specific selections on top. Takes the PREVIOUS order as `base` only so
 * fields the picker doesn't own (nothing today) would survive a re-seed —
 * `chooseService` and `orderFromIntent` both currently pass a full record in.
 */
function seedOrder(base: Order, cat: Catalog, k: ServiceKey): Order {
  const rec = cat.plans.find((p) => p.recommended) ?? cat.plans[0];
  return {
    ...base,
    service: k,
    planId: k === "vps" ? rec?.id ?? null : null,
    // NOT `cat.regions[0]` — with no explicit `orderBy` on the `Node` query
    // this fed the wizard's picker, `regions[0]` was whatever order Postgres
    // happened to return rows in, so a fresh order could seed a random
    // region. `defaultRegionKey` is resolved server-side, deterministically
    // (closest-to-visitor via geoip, else a fixed default) — see
    // lib/nx/catalog.ts.
    region: cat.defaultRegionKey ?? cat.regions[0]?.key ?? null,
    /* Must be a PLAIN_OS. Taking `oses[0]` picked whatever sorted first, and
       once the real catalogue landed that was Docker — an APPLICATION — so a
       fresh order defaulted to "operating system: Docker".
       Prefer the newest Ubuntu specifically — the most recognisable, most
       requested default — over whichever PLAIN_OS row happens to sort
       first alphabetically (AlmaLinux, before this). Falls back to the old
       "first PLAIN_OS" behavior if Ubuntu isn't in the catalogue at all. */
    osId: (
      cat.oses
        .filter((x) => x.category === "PLAIN_OS" && x.family === "ubuntu")
        .sort((a, b) => parseFloat(b.version || "0") - parseFloat(a.version || "0"))[0]
      ?? cat.oses.find((x) => x.category === "PLAIN_OS")
      ?? cat.oses[0]
    )?.id ?? null,
    termMonths: 1,
    /* A randomized "vps-xxxx" per order, never the same literal twice — was a
       hardcoded "web-01" until 2026-09-24, when production turned out to have
       7 unrelated customers all sharing that exact default (see
       lib/hostname.ts's doc comment for the resulting cross-customer
       data-exposure incident). Still only a STARTING point, not a uniqueness
       guarantee on its own: hostCheck below live-checks it (and whatever the
       customer edits it to) against the real DB as they type. */
    hostname: k === "vps" ? genDefaultVpsHostname() : "",
    serverName: k === "game" ? "My server" : "",
    addons: [],   // nothing that costs money is pre-selected
    diskGb: 0,
    /* A game order starts with NO family chosen — the picker is the next step,
       and pre-selecting one would put a product in the cart nobody asked for. */
    gameFamily: null, gamePlanId: null, gameVariant: null, subdomain: "",
    /* Hosting and email are bought against a DOMAIN, which only the customer
       can supply — there is no sensible default, so the field starts empty
       and the step is not "done" until they type one. */
    domain: "",
    subdomainLabel: "",
    /* Both seed their cheapest plan so the order is immediately priceable. */
    hostingPlanId: k === "hosting" ? (cat.hosting[0]?.id ?? null) : null,
    emailPlanId: k === "email" ? (cat.email[0]?.id ?? null) : null,
  };
}

/** Reads a `DeployIntent` back off the URL, using the exact keys
 *  `lib/deploy-intent.ts`'s `deployHref` wrote — see that file for why each
 *  field has the query key it has. */
function parseIntent(sp: URLSearchParams): DeployIntent {
  const raw = (k: keyof DeployIntent) => sp.get(DEPLOY_PARAM[k]);
  const num = (k: keyof DeployIntent) => {
    const v = raw(k);
    if (!v) return undefined;
    const n = Number(v);
    return Number.isFinite(n) ? n : undefined;
  };
  const serviceRaw = raw("service");
  const service: DeployService | undefined =
    serviceRaw === "vps" || serviceRaw === "game" || serviceRaw === "hosting" || serviceRaw === "email"
      ? serviceRaw
      : undefined;
  const addonsRaw = raw("addons");
  return {
    service,
    planId: raw("planId") ?? undefined,
    termMonths: num("termMonths"),
    region: raw("region") ?? undefined,
    addons: addonsRaw ? addonsRaw.split(",").map((s) => s.trim()).filter(Boolean) : undefined,
    diskGb: num("diskGb"),
    gameFamily: raw("gameFamily") ?? undefined,
    gamePlanId: raw("gamePlanId") ?? undefined,
    gameVariant: raw("gameVariant") ?? undefined,
    players: num("players"),
    hostingPlanId: raw("hostingPlanId") ?? undefined,
    emailPlanId: raw("emailPlanId") ?? undefined,
    couponCode: raw("couponCode") ?? undefined,
  };
}

/** The tier that best fits a desired headcount: the smallest slotted tier
 *  that still covers it, or — past the top of the ladder, or when the family
 *  has no slotted tiers at all — the single most expensive one, the closest
 *  real thing this family sells to "give me your biggest". Same judgment call
 *  GameLandingCombined's own player-count slider already makes, just applied
 *  against the LIVE catalogue instead of that page's illustrative fixture. */
function nearestTierBySlots(tiers: GameTier[], players: number): string | null {
  if (tiers.length === 0) return null;
  const slotted = tiers.filter((t): t is GameTier & { slots: number } => t.slots != null);
  const fits = slotted.filter((t) => t.slots >= players).sort((a, b) => a.slots - b.slots)[0];
  if (fits) return fits.id;
  const pool = slotted.length ? slotted : tiers;
  return [...pool].sort((a, b) => a.monthlyCents - b.monthlyCents).at(-1)?.id ?? null;
}

/**
 * Materializes a `DeployIntent` into a real, catalogue-validated `Order` —
 * every id is checked against `cat` before it's used, so a stale or tampered
 * query string (an old link to a plan that's since been deactivated, say)
 * degrades to `seedOrder`'s normal defaults for whatever field didn't match,
 * never to a broken or half-filled order. Returns null when the URL carries
 * no recognised `product`, so the wizard opens on its ordinary empty first
 * step exactly as it always has.
 */
function orderFromIntent(cat: Catalog, intent: DeployIntent): Order | null {
  if (!intent.service) {
    // No specific service in the URL — but a coupon may still be attached
    // (a promo CTA that deliberately lands on the plain service picker
    // rather than defaulting into one product, e.g. lib/actions-promo-trial.ts's
    // ANY-service trial coupon — "works on any Game Server or Cloud VPS
    // plan" stops being true in practice if the button always drops the
    // customer into Game Servers specifically). Carry the coupon into the
    // ordinary empty first step instead of dropping it entirely.
    return intent.couponCode ? { ...EMPTY, couponCode: intent.couponCode } : null;
  }
  const o = seedOrder(EMPTY, cat, intent.service);
  // Applied regardless of which service branch runs below — a coupon covering
  // "any VPS or Game Server" (see lib/promo-trial.ts) isn't service-specific,
  // it just needs a real order to attach to.
  if (intent.couponCode) o.couponCode = intent.couponCode;

  const term = intent.termMonths;
  if (term != null && cat.terms.some((t) => t.months === term)) o.termMonths = term;

  // A region is not VPS-specific — game orders carry one too (`o.region`
  // gates the wizard's Region step for both). This used to live inside the
  // `vps`-only branch below, so a marketing page's "closest region" choice
  // (e.g. a game's own region picker, or `?region=fsn1` on a deploy link)
  // was read off the URL, matched against the real catalogue, and then
  // silently thrown away the moment `intent.service === "game"` — the
  // customer picked Germany on the marketing site and landed back on
  // whatever `seedOrder` defaulted to. Applied once, before the
  // per-service branches, so both paths get it.
  if (intent.region && cat.regions.some((r) => r.key === intent.region)) { o.region = intent.region; o.regionPicked = true; }

  if (intent.service === "vps") {
    if (intent.planId && cat.plans.some((p) => p.id === intent.planId)) o.planId = intent.planId;
    if (intent.addons?.length) {
      const valid = new Set<string>(cat.addons.map((a) => a.key));
      const picked = intent.addons.filter((a) => valid.has(a));
      if (picked.length) o.addons = picked;
    }
    if (intent.diskGb != null && intent.diskGb >= 0) o.diskGb = Math.round(intent.diskGb);
  }

  if (intent.service === "game") {
    const g = intent.gameFamily ? cat.games.find((x) => x.family === intent.gameFamily) : null;
    if (g) {
      o.gameFamily = g.family;
      const exact = intent.gamePlanId ? g.tiers.find((t) => t.id === intent.gamePlanId) : null;
      o.gamePlanId =
        exact?.id
        ?? (intent.players && intent.players > 0 ? nearestTierBySlots(g.tiers, intent.players) : null)
        ?? [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0]?.id
        ?? null;
      o.gameVariant =
        intent.gameVariant && g.variants.some((v) => v.id === intent.gameVariant)
          ? intent.gameVariant
          : g.defaultVariant;
    }
  }

  if (intent.service === "hosting" && intent.hostingPlanId && cat.hosting.some((h) => h.id === intent.hostingPlanId)) {
    o.hostingPlanId = intent.hostingPlanId;
  }

  if (intent.service === "email" && intent.emailPlanId && cat.email.some((e) => e.id === intent.emailPlanId)) {
    o.emailPlanId = intent.emailPlanId;
  }

  return o;
}

const C = createContext<Ctx>(null as unknown as Ctx);
export const useOrder = () => useContext(C);

export function OrderProvider({ cat: baseCat, children }: { cat: Catalog; children: React.ReactNode }) {
  /* One-off custom plans built in THIS session. They are real (inactive,
     sortOrder 999) Plan/GamePlan rows the server just created, but they are not
     in the page's catalogue — so they are merged in here, and every lookup
     below (`plan`, `game.tiers`, the summary, the bottom bar) finds them
     exactly like a catalogue row. One custom build per product/family: a
     rebuild replaces the previous one rather than piling up cards. */
  const [customPlans, setCustomPlans] = useState<PlanOption[]>([]);
  const [customTiers, setCustomTiers] = useState<Record<string, GameTier[]>>({});
  const cat = useMemo<Catalog>(() => {
    if (customPlans.length === 0 && Object.keys(customTiers).length === 0) return baseCat;
    return {
      ...baseCat,
      plans: [...baseCat.plans, ...customPlans],
      games: baseCat.games.map((g) =>
        customTiers[g.family]?.length ? { ...g, tiers: [...g.tiers, ...customTiers[g.family]] } : g),
    };
  }, [baseCat, customPlans, customTiers]);
  // Read once, on mount: a marketing "Deploy" button's selection, carried here
  // via `/dashboard/deploy?product=...` (see lib/deploy-intent.ts) — including
  // unchanged across a login/signup detour, since that's just the existing
  // `?next=` convention carrying this same query string through (see
  // lib/safe-next.ts, app/login/page.tsx, app/dashboard/layout.tsx).
  // `useSearchParams()` needs this component under a Suspense boundary, which
  // app/dashboard/deploy/page.tsx provides around <DeployView>.
  const searchParams = useSearchParams();
  const [o, setO] = useState<Order>(() => orderFromIntent(cat, parseIntent(searchParams)) ?? EMPTY);
  const [price, setPrice] = useState<CartPrice>(null);
  const [pricing, setPricing] = useState(false);
  const [priceError, setPriceError] = useState<string | null>(null);
  const [hostCheck, setHostCheck] = useState<AvailabilityCheck>({ status: "idle" });

  const set = useCallback(<K extends keyof Order>(k: K, v: Order[K]) => {
    setO((p) => ({ ...p, [k]: v }));
  }, []);

  const chooseService = useCallback((k: ServiceKey) => {
    // Re-clicking the service tile that's already active must be a no-op —
    // this used to unconditionally reseed (fresh plan/term/hostname/addons),
    // so a customer who'd already configured VPS and tapped the "Cloud VPS"
    // tile again (e.g. from the rail, or a stray double-tap) lost everything
    // they'd picked below. Returning the SAME object (not a shallow copy)
    // also skips the reseed effects that key off a new `o` reference.
    setO((p) => (p.service === k ? p : seedOrder(p, cat, k)));
  }, [cat]);

  /* Choosing a family seeds its cheapest tier and its default loader, so the
     order is immediately priceable; the customer changes what they care about. */
  const chooseGame = useCallback((family: string) => {
    // Same idempotency as chooseService above, one level down: re-picking the
    // family that's already selected must not reset the tier/variant/config
    // the customer already chose on the Server step back to the cheapest
    // tier and empty config.
    setO((p) => {
      if (p.gameFamily === family) return p;
      const g = cat.games.find((x) => x.family === family);
      if (!g) return p;
      const cheapest = [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0];
      return {
        ...p,
        gameFamily: family,
        gamePlanId: cheapest?.id ?? null,
        gameVariant: g.defaultVariant,
