"use server";

import { requireUser } from "@/lib/auth";
import { orderQuote, OrderError, type OrderIntent } from "@/lib/order";
import { headers } from "next/headers";
import { couponAccountEligibilityError } from "@/lib/coupon-redemption";
import { hashIp } from "@/lib/coupon-order";
import { clientIp } from "@/lib/rate-limit";

/* Live pricing for the deploy wizard.
 *
 * WHY THIS FILE EXISTS AT ALL. The design's wizard shows a running total that
 * updates as you pick a plan, a term, add-ons and disk. The design sandbox
 * computed that total in the browser from a fixture table. That must not
 * survive the port: a price the VIEW derives is a second pricing formula, and
 * the moment it disagrees with `orderQuote` the customer is shown one number
 * and charged another. So the wizard asks the server what things cost, every
 * time, and renders only what comes back.
 *
 * WHY IT IS ITS OWN FILE. `"use server"` makes EVERY export in a module
 * network-callable by anyone who can reach the app. This module therefore
 * exports exactly one thing, and that thing:
 *   - requires a signed-in user,
 *   - only READS (orderQuote never writes, never charges, never reserves),
 *   - returns a price, never an order.
 * Do not add a second export here, and do not let anything that mutates share
 * this file. The same property is why lib/safe-next.ts and lib/totp-verify.ts
 * were split out — in this codebase that mistake has already produced one
 * public brute-force oracle.
 */

export type QuotedPrice = {
  ok: true;
  /** Net, pre-tax, in cents — the figure every other number is derived from. */
  chargeCents: number;
  /** What is actually taken: `chargeCents + taxCents`. */
  taxCents: number;
  totalCents: number;
  months: number;
  /** Regular (undiscounted) plan cash for the term, for an honest "was" price. */
  regularPlanCents: number;
  /* A promo is only reported when it actually MOVED the price. `orderQuote`
     returns the active promo's name regardless of whether it applied to this
     product — first-month-free is hosting-only, so a VPS order came back
     carrying "First month free" while being charged in full. Showing that is
     worse than showing nothing: it tells the customer they are not paying for
     something they are paying for. */
  promoName: string;
  promoPercent: number;
  promoCreditCents: number;
  couponLabel: string | null;
  couponDiscountCents: number;
  couponError: string | null;
  extraDiskCents: number;
  backupCents: number;
  /** Intro pricing, so the wizard can say "then $X/mo" rather than implying
      forever. Both are null unless the plan ACTUALLY carries an intro rate —
      a renewal figure shown without one just restates the price as a warning. */
  introMonthlyCents: number | null;
  introRenewalMonthly: number | null;
  /** What this order actually renews at, every cycle — plan (no coupon/intro
   *  discount, both first-term-only) plus every recurring add-on at full
   *  price. Always populated, unlike introRenewalMonthly. See lib/order.ts's
   *  renewalTotalCents for the full reasoning. */
  renewalTotalCents: number;
  /**
   * CREATOR PARTNER PROGRAM (2026-09-26): how much of `chargeCents` is this
   * customer's partner discount, and at what tier — "FIRST" (50% off, a genuine
   * first purchase), "RECURRING" (10% off, every purchase after), or "NONE" (not
   * attached to an active partner — the overwhelming majority). The wizard shows
   * this BEFORE checkout so the discount is visible ahead of the first purchase,
   * per the program's own requirement.
   */
  partnerDiscountCents: number;
  partnerDiscountPercent: number;
  partnerDiscountTier: "FIRST" | "RECURRING" | "NONE";
  partnerName: string | null;
};

export type QuoteResult = QuotedPrice | { ok: false; error: string };
