export function Shell({ children, user, badges = {}, notifications = [] }: {
  children: React.ReactNode; user: User; badges?: Badges; notifications?: Note[];
}) {
  // The composer lives at the SHELL level, exactly as it does in the portal
  // shell this one replaces. Two reasons it cannot move down into the mail
  // page: App Router keeps the shell mounted across in-portal navigation, so an
  // open (or minimized) composer and its in-progress draft survive moving
  // between pages; and MailClient calls `useCompose()` unconditionally, which
  // THROWS when no provider sits above it.
  //
  // That throw is not hypothetical — it took the whole inbox down. This shell
  // reproduced the portal shell's layout but not this provider, and the crash
  // is invisible until an account has a real, reachable mailbox: with none, the
  // mail page short-circuits to "No email plan yet" and never renders
  // MailClient at all. The first account with working mail gets an error
  // boundary instead of an inbox.
  // The SECOND provider this shell failed to reproduce, and the same bug
  // shape: `OpenTerminalButton` calls `useTerminalDock()`, which throws outside
  // a provider, so every RUNNING VPS detail page — and any game server whose
  // family check sent it down the VPS branch — rendered an error boundary
  // instead of a server. Invisible from the routes a smoke test walks, because
  // the button only mounts on a server's own page when it is running.
  //
  // MatrixPanel is the same omission a third time. It is mounted HERE rather
  // than by /dashboard/build's page because the App Router unmounts a page's
  // subtree on every route change, and Matrix's whole promise is that you can
  // leave a build running, go look at something else in the portal, and come
  // back to it still running. Mounted at the shell, its consoles and their
  // websockets outlive navigation. It renders nothing until the route is first
  // visited, so accounts that never open it pay nothing for it.
  return (
    <ComposeProvider>
      <TerminalDockProvider>
        <ShellInner user={user} badges={badges} notifications={notifications} matrixPanel={<MatrixPanel />}>
          {children}
        </ShellInner>
      </TerminalDockProvider>
    </ComposeProvider>
  );
}
