/**
 * Stripe LOCAL payment methods (PayNow, GrabPay, UPI, Alipay, WeChat Pay) for
 * wallet top-ups. PURE — no db, no settings, no Stripe client — so the rules are
 * unit-testable and safe to import from client components. The DB-backed half
 * (which methods are switched on right now) is lib/local-payments.ts.
 *
 * WHY WALLET TOP-UPS ONLY. Every local method here is a one-time, customer-present
 * payment: none can be saved and charged off-session the way a card can, and the
 * platform's renewals draw from a saved card or the wallet. So a local method is
 * offered where money lands in the WALLET (Add funds), and the wallet then pays
 * the order or the renewal. They are deliberately NOT offered as a way to pay an
 * order directly, which would break auto-renewal and the purchase-leg fulfilment
 * (lib/stripe.ts `isPurchaseLegSession`) that assumes a card/wallet funding leg.
 *
 * WHICH METHODS ARE REAL FOR US. A method is only available to a merchant whose
 * Stripe account is registered in a supporting country. The source for the table
 * below is Stripe's payment-method support table as read into the growth backlog
 * on 2026-10-01 (mkt-016): PayNow is Singapore merchants only; GrabPay is
 * Malaysia/Singapore; UPI includes Canada and Singapore; Alipay and WeChat Pay
 * are offered to Canadian accounts. Our Stripe entity's country is NOT verified
 * in the repo (it is read from the `stripe_account_country` setting, blank by
 * default), so with no country set NO local method is offered. Not offered:
 * GCash and QRIS (no native Stripe support for an SG account, no local PSP is
 * integrated) and FPX/PromptPay (we do not hold a MY/TH entity).
 *
 * CHARGE CURRENCY. PayNow and GrabPay can only be charged in SGD, UPI in INR.
 * Nothing in the repo supplies a trustworthy FX rate (lib/currency.ts's table is
 * documented as a coarse display snapshot), so a non-USD method is unavailable
 * until an admin enters a rate for that currency (`local_pay_fx_rates`). The
 * customer is charged `usd x rate x (1 + buffer)` rounded UP; the wallet is
 * credited exactly the USD amount they asked for. Alipay and WeChat Pay are
 * requested in USD (both support it per Stripe's currency table) so they need no
 * rate; if Stripe refuses that for the account, session creation fails cleanly
 * and the customer sees the error — nothing is charged.
 */

export type LocalMethodId = "paynow" | "grabpay" | "upi" | "alipay" | "wechat_pay";

export type LocalMethod = {
  id: LocalMethodId;
  /** Stripe `payment_method_types` value. */
  stripeType: string;
  label: string;
  /** Currency Stripe will charge the customer in (ISO 4217, upper case). */
  chargeCurrency: string;
  /** Stripe-account countries that can accept this method. */
  entityCountries: readonly string[];
  /** Customer countries this method is for (landing-page display + suggestion order). */
  customerCountries: readonly string[];
  /** One honest line for the picker. */
  note: string;
};

export const LOCAL_METHODS: Record<LocalMethodId, LocalMethod> = {
  paynow: {
    id: "paynow", stripeType: "paynow", label: "PayNow", chargeCurrency: "SGD",
    entityCountries: ["SG"], customerCountries: ["SG"],
    note: "Scan the QR code in your banking app. Charged in Singapore dollars.",
  },
  grabpay: {
    id: "grabpay", stripeType: "grabpay", label: "GrabPay", chargeCurrency: "SGD",
    entityCountries: ["SG"], customerCountries: ["SG", "MY"],
    note: "Pay from your Grab wallet. Charged in Singapore dollars.",
  },
  upi: {
    id: "upi", stripeType: "upi", label: "UPI", chargeCurrency: "INR",
    entityCountries: ["SG", "CA"], customerCountries: ["IN"],
    note: "Pay with any UPI app. Charged in Indian rupees.",
  },
  alipay: {
    id: "alipay", stripeType: "alipay", label: "Alipay", chargeCurrency: "USD",
    entityCountries: ["CA"], customerCountries: ["CN", "HK", "MY", "SG"],
    note: "Pay with the Alipay app.",
  },
  wechat_pay: {
    id: "wechat_pay", stripeType: "wechat_pay", label: "WeChat Pay", chargeCurrency: "USD",
    entityCountries: ["CA"], customerCountries: ["CN", "HK", "SG"],
    note: "Pay with the WeChat app.",
  },
};

export const LOCAL_METHOD_IDS = Object.keys(LOCAL_METHODS) as LocalMethodId[];

export function isLocalMethodId(v: unknown): v is LocalMethodId {
  return typeof v === "string" && Object.prototype.hasOwnProperty.call(LOCAL_METHODS, v);
}

/** Setting key holding a method's on/off flag (default "false" — see lib/settings.ts). */
export const localMethodFlagKey = (id: LocalMethodId) => `pay_method_${id}`;

/** True when a Stripe account registered in `entityCountry` can take this method. */
export function methodSupportedByEntity(id: LocalMethodId, entityCountry: string | null | undefined): boolean {
  const c = (entityCountry ?? "").trim().toUpperCase();
  if (c.length !== 2) return false;
  return LOCAL_METHODS[id].entityCountries.includes(c);
}

/**
 * Parse the `local_pay_fx_rates` setting: a JSON object of currency -> units of
 * that currency per 1 USD, e.g. {"SGD":1.3,"INR":83}. Anything malformed,
 * non-positive or non-finite is dropped, so a typo can only make a method
 * unavailable, never charge a wrong amount. USD is always 1.
 */
export function parseLocalFxRates(json: string | null | undefined): Record<string, number> {
  const out: Record<string, number> = { USD: 1 };
  if (!json) return out;
  try {
    const raw = JSON.parse(json);
    if (raw && typeof raw === "object" && !Array.isArray(raw)) {
      for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
        const code = k.trim().toUpperCase();
        const rate = typeof v === "number" ? v : Number(v);
        if (/^[A-Z]{3}$/.test(code) && code !== "USD" && Number.isFinite(rate) && rate > 0 && rate < 1_000_000) {
          out[code] = rate;
        }
      }
    }
  } catch { /* unreadable -> only USD */ }
  return out;
}

/**
 * What to charge in the method's own currency for a wallet credit of `usdCents`.
 * `null` = cannot be priced (no admin rate for that currency). Rounded UP to the
 * smallest currency unit so FX rounding never leaves the wallet short-funded.
 * All supported currencies here are two-decimal (SGD, INR, USD).
 */
export function localChargeCents(opts: {
  usdCents: number;
  method: LocalMethodId;
  rates: Record<string, number>;
  bufferPct: number;
}): number | null {
  const { usdCents, method, rates } = opts;
  if (!Number.isInteger(usdCents) || usdCents <= 0) return null;
  const cur = LOCAL_METHODS[method].chargeCurrency;
  const rate = cur === "USD" ? 1 : rates[cur];
  if (!(typeof rate === "number" && rate > 0 && Number.isFinite(rate))) return null;
  const buffer = cur === "USD" ? 0 : Math.min(Math.max(Number.isFinite(opts.bufferPct) ? opts.bufferPct : 0, 0), 20);
  // Round to 6 dp before ceil so float noise (1.3 * 100 = 130.00000000000003) can't add a unit.
  const raw = Math.round(usdCents * rate * (1 + buffer / 100) * 1e6) / 1e6;
  return Math.ceil(raw);
}

/**
 * The USD cents a PAID Checkout Session should add to the wallet.
 *
 * Before local methods every session was USD, so the credit was simply
 * `amount_total`. A non-USD session's `amount_total` is in a DIFFERENT currency's
 * cents, so crediting it verbatim would hand out e.g. 1.3x the money. A local
 * session therefore carries the USD credit it was priced for in its own metadata
 * (set server-side at creation, `nxeonCreditUsdCents`), and this function:
 *   - USD session, no local-method marker  -> `amount_total` (unchanged behaviour);
 *   - local-method session                 -> the metadata credit, but only if the
 *     method is known AND the session really was charged in that method's
 *     currency (a mismatched/tampered session credits nothing);
 *   - any other non-USD session            -> 0 (refuse rather than guess).
 */
export function walletCreditCents(session: {
  amount_total?: number | null;
  currency?: string | null;
  metadata?: Record<string, string> | null;
}): number {
  const total = session.amount_total ?? 0;
  const cur = (session.currency ?? "usd").toUpperCase();
  const marker = session.metadata?.nxeonLocalPay;
  if (!marker) return cur === "USD" && Number.isInteger(total) && total > 0 ? total : 0;
  if (!isLocalMethodId(marker)) return 0;
  if (cur !== LOCAL_METHODS[marker].chargeCurrency) return 0;
  const credit = Number(session.metadata?.nxeonCreditUsdCents);
  if (!Number.isInteger(credit) || credit <= 0) return 0;
  // A USD-charged local session must credit exactly what it charged.
  if (cur === "USD" && credit !== total) return 0;
  return credit;
}

