"use client";

import { useActionState, useState } from "react";
import { topUp } from "@/lib/actions";
import { Badge } from "@/components/ui/primitives";
import { AddFundsPaymentModal } from "@/components/customer/AddFundsPaymentModal";

const PRESETS = [10, 25, 50, 100];

function DemoTopUp() {
  const [state, action, pending] = useActionState(topUp, {});
  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
  // `<form action={fn}>` submit — including a REJECTED one. `topUp` returns
  // `{error}`, so an uncontrolled amount snapped back to the default while the
  // error pointed at a figure no longer on screen. Same reset class as
  // AutoRecharge.tsx.
  const [amount, setAmount] = useState("25");
  return (
    <div>
      <div className="mb-3 flex items-center gap-2">
        <Badge tone="amber">demo gateway</Badge>
        <span className="text-xs text-slate-500">
          Card payments are not configured — funds are credited instantly for testing.
        </span>
      </div>
      <form action={action} className="flex items-end gap-3">
        <div>
          <label className="label">Amount (USD)</label>
          <input
            className="input w-36"
            name="amount"
            type="number"
            min={1}
            max={1000}
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
        </div>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Adding…" : "Add funds"}
        </button>
        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
      </form>
    </div>
  );
}

export function AddFunds() {
  const [amount, setAmount] = useState<string>("25");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [demoMode, setDemoMode] = useState(false);
  const [session, setSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);

  if (demoMode) return <DemoTopUp />;

  const checkout = async () => {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/stripe/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amount: Number(amount) }),
      });
      const json: { clientSecret?: string; publishableKey?: string; error?: string } = await res
        .json()
        .catch(() => ({}));
      if (json.clientSecret && json.publishableKey) {
        // Pay in the embedded modal on THIS page — no redirect to Stripe.
        setSession({ clientSecret: json.clientSecret, publishableKey: json.publishableKey });
        setBusy(false);
        return;
      }
      const msg = json.error ?? "Checkout failed — try again.";
      if (msg.toLowerCase().includes("not configured")) {
        setDemoMode(true);
      } else {
        setError(msg);
      }
    } catch {
      setError("Network error — try again.");
    }
    setBusy(false);
  };

  const n = Number(amount);
  const valid = Number.isFinite(n) && n >= 5 && n <= 5000;

  return (
    <div>
      <div className="flex flex-wrap items-end gap-3">
        <div>
          <label className="label">Amount (USD)</label>
          <div className="flex items-center gap-2">
            {PRESETS.map((p) => (
              <button
                key={p}
                type="button"
                onClick={() => setAmount(String(p))}
                className={`chip h-[30px] px-3 text-[12px] ${amount === String(p) ? "chip-on" : ""}`}
              >
                ${p}
              </button>
            ))}
            <input
              className="input w-28"
              type="number"
              min={5}
              max={5000}
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          </div>
        </div>
        <button className="btn-primary" onClick={() => void checkout()} disabled={busy || !valid}>
          {busy ? "Loading…" : "Add funds"}
        </button>
      </div>
      {!valid && amount !== "" && (
        <p className="mt-2 text-xs text-amber-300">Amount must be between $5 and $5000.</p>
      )}
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      <p className="mt-2 text-xs text-slate-500">Secure card checkout powered by Stripe.</p>
      {session && (
        <AddFundsPaymentModal
          clientSecret={session.clientSecret}
          publishableKey={session.publishableKey}
          amountCents={Math.round(n * 100)}
          onClose={() => setSession(null)}
        />
      )}
    </div>
  );
}
