import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { enabledLocalMethods, localPaymentConfig } from "@/lib/local-payments";
import { localChargeCents } from "@/lib/local-payment-methods";

/**
 * The local payment methods the Add-funds picker may offer RIGHT NOW (default:
 * none). Read-only. Signed-in only: the picker lives on the Billing page, and
 * there is no reason to publish which methods are switched on to the open web.
 * Marketing pages use `enabledLocalMethods` server-side instead.
 */
export const dynamic = "force-dynamic";

export async function GET() {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const [methods, cfg] = await Promise.all([enabledLocalMethods(), localPaymentConfig()]);
  return NextResponse.json({
    methods: methods.map((m) => ({
      id: m.id,
      label: m.label,
      note: m.note,
      currency: m.chargeCurrency,
      // Price of $10 in the method's currency, so the picker can say what will be charged
      // before the customer commits. null never happens for an enabled method.
      tenDollarsInCurrency: localChargeCents({ usdCents: 1000, method: m.id, rates: cfg.rates, bufferPct: cfg.bufferPct }),
    })),
  });
}
