// HAND-WRITTEN (not generated): the one dynamic route serving every generated
// location landing of the live site (app/(marketing)/[slug]: region tier, city
// matrix, general per-location pages, game x location matrix) plus the
// Singapore landers — ~770 slugs, resolved by the live builders in
// app/nxm/_data/location-landing.ts (unknown slugs 404). Static /nxm routes
// always win over this segment in Next, so it can never shadow a ported page.
//
// Two templates, like the live route: game x location combos render through
// the design's game x location page (generated by tools/nxm/port_pages.py as
// "minecraft-server-hosting-singapore"), everything else through the location
// template (tools/nxm/native/location-landing).
import type { Metadata } from "next";
import { NxmPage } from "../_components/NxmPage";
import { nxmMetadata } from "../_seo/meta";
import * as L from "../_pages/location-landing/content";
import * as G from "../_pages/minecraft-server-hosting-singapore/content";
import { load, meta } from "../_data/location-landing";
import { nxmParams } from "../_data/params";
import "../_pages/location-landing/page.css";
import "../_pages/minecraft-server-hosting-singapore/page.css";

export const dynamic = "force-dynamic";

type Props = { params: Promise<Record<string, string>>; searchParams: Promise<Record<string, string | string[] | undefined>> };

export async function generateMetadata({ params, searchParams }: Props): Promise<Metadata> {
  const p = await nxmParams(params, searchParams, {});
  return nxmMetadata(`/${p.slug}`, await meta(p));
}

export default async function Page({ params, searchParams }: Props) {
  const p = await nxmParams(params, searchParams, {});
  const d = await load(p);
  const game = d.template === "game";
  const C = game ? G : L;
  return (
    <NxmPage
      slug={game ? "minecraft-server-hosting-singapore" : "location-landing"}
      route={`/${p.slug}`}
      body={C.BODY_HTML}
      attrs={C.BODY_ATTRS}
      particles={d.particles}
      slots={d.slots}
      data={d.data}
      jsonLd={d.jsonLd}
      crumb={d.crumb}
      trail={d.trail}
    />
  );
}
