 * also only renders for the products the terms cover (a paid server or hosting plan):
 * not business email, not domains.
 */
export function MoneyBackNote({ className = "" }: { className?: string }) {
  const { o, cat } = useOrder();
  const mb = cat.moneyBack;
  if (!mb) return null;
  if (o.service !== "vps" && o.service !== "game" && o.service !== "hosting") return null;
  return (
    <details className={"group text-[11.5px] leading-[1.45] text-tx-faint " + className}>
      <summary className="flex cursor-pointer list-none items-center gap-2 [&::-webkit-details-marker]:hidden"
               title={mb.terms}>
        <Icon name="shieldcheck" size={13} className="flex-none text-mint" />
        <span className="font-semibold text-mint">{mb.label}</span>
