export type GameQuoteResult = GameQuoted | { ok: false; error: string };

/**
 * Price a game selection. Read-only.
 *
 * Errors are RETURNED rather than thrown: a half-made selection is the normal
 * state of a wizard, not an exception, and the cart should show nothing rather
 * than an error boundary.
 */
export async function quoteGameOrder(intent: GameOrderIntent): Promise<GameQuoteResult> {
  const user = await requireUser();
  try {
    let q = await gameOrderQuote(intent, { userId: user.id });
    // Catalog-level checks (service/plan/term/dates/global cap) already ran
    // inside gameOrderQuote; this adds the two ACCOUNT-level ones it can't see
    // — see couponAccountEligibilityError's own doc comment for why the
    // preview needs this too, not just the real reservation at pay time.
    let couponError: string | null = q.couponError || null;
    if (q.couponId && q.couponDiscountCents > 0) {
      const ineligible = await couponAccountEligibilityError({
        userId: user.id,
        firstTimeOnly: q.couponFirstTimeOnly,
        excludeActiveCustomers: q.couponExcludeActiveCustomers,
        couponId: q.couponId,
        ipHash: hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null,
      });
      if (ineligible) {
        // Re-price WITHOUT the coupon — exactly what payAndDeployGame's card
        // path does when the hold is refused. Not "add the coupon back" onto
        // chargeCents: the partner discount is a percentage of the post-coupon
        // amount, so adding the coupon back left the partner line computed on
        // the wrong base and the total a few cents/dollars off the real charge
        // (2026-09-28).
        q = await gameOrderQuote({ ...intent, couponCode: undefined }, { userId: user.id });
        couponError = ineligible;
      }
    }
    const couponDiscountCents = q.couponDiscountCents ?? 0;
    const couponLabel: string | null = q.couponLabel || null;
    return {
      ok: true,
      chargeCents: q.chargeCents,
      monthlyCents: q.monthlyCents,
      months: q.term,
      planName: q.planName,
      gameFamily: q.gameFamily,
      hostname: q.hostname,
      subdomain: q.subdomain,
      variant: q.variant,
      introPercent: q.introPercent,
      couponLabel,
      couponDiscountCents,
      couponError,
      renewalTotalCents: q.renewalTotalCents ?? q.chargeCents,
      partnerDiscountCents: q.partnerDiscountCents ?? 0,
      partnerDiscountPercent: q.partnerDiscountPercent ?? 0,
      partnerDiscountTier: q.partnerDiscountTier ?? "NONE",
      partnerName: q.partnerName ?? null,
    };
  } catch (e) {
    // The real reason when it is one the customer can act on (an unsupported
    // term, a taken subdomain); never an internal message.
    return { ok: false, error: e instanceof Error ? e.message : "Couldn't price that selection." };
  }
}
import net from "node:net";

/**
 * Dependency-free, in-memory sliding-window rate limiter.
 *
 * Suitable for single-process app-level throttling (login attempts, etc).
 * State lives in a module-level Map; on a horizontally-scaled deployment each
 * instance limits independently — acceptable for auth-abuse mitigation. A
 * background sweep prunes empty buckets so the Map does not grow unbounded.
 */

type Bucket = number[]; // sorted-ish list of hit timestamps (ms)

const buckets = new Map<string, Bucket>();

// Persist the Map across HMR / route reloads in dev.
const globalForRl = globalThis as unknown as { __nxeonRateLimit?: Map<string, Bucket> };
const store: Map<string, Bucket> = globalForRl.__nxeonRateLimit ?? buckets;
if (process.env.NODE_ENV !== "production") globalForRl.__nxeonRateLimit = store;

export type RateLimitOptions = { max: number; windowMs: number };
export type RateLimitResult = { ok: boolean; retryAfterSec: number; remaining: number };

/**
 * The widest window any caller has ever asked for.
 *
 * The sweep below used a HARDCODED 15-minute horizon while callers pass windows
 * far longer than that — `RESEND_LIMIT` in lib/email-verification.ts is an hour,
 * as are the mail-send, calendar-mutation, org-invite and wallet-top-up limits.
 * A bucket whose last hit was 16 minutes ago was therefore DELETED, and deleting
let widestWindowMs = 15 * 60 * 1000;

/**
 * Record and check a hit for `key`. Returns `{ ok, retryAfterSec, remaining }`.
 * When `ok` is false the caller should reject and surface `retryAfterSec`.
 */
export function checkRateLimit(key: string, { max, windowMs }: RateLimitOptions): RateLimitResult {
  const now = Date.now();
  if (windowMs > widestWindowMs) widestWindowMs = windowMs;
  sweep(now);
  const cutoff = now - windowMs;
  const hits = (store.get(key) ?? []).filter((t) => t > cutoff);

  if (hits.length >= max) {
    const oldest = hits[0];
    const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
    store.set(key, hits); // persist the pruned window
    return { ok: false, retryAfterSec, remaining: 0 };
  }

  hits.push(now);
  store.set(key, hits);
  return { ok: true, retryAfterSec: 0, remaining: max - hits.length };
}

/** Clear the window for a key (e.g. after a successful login). */
export function resetRateLimit(key: string): void {
 * the shared `UNKNOWN_IP` bucket, which is conservative rather than private.
 *
 * DEPLOYMENT COUPLING: correct for exactly `TRUSTED_PROXY_HOPS` reverse proxies
 * in front of the app. If a CDN is ever added, raise that env var; the fix is
 * never to go back to reading the leftmost hop.
 */
export function clientIp(source: ClientIpSource): string {
  const h = headersOf(source);
  const hops = (h.get("x-forwarded-for") ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  if (hops.length > 0) {
    // Walk back past the proxies we run. Clamped at 0 so a misconfigured hop
    // count degrades to "the leftmost entry" instead of throwing, and keep
    // walking left while the entry is not a valid address — a junk value at the
    // trusted position must not become a bucket key of its own.
