"use client";

import Link from "next/link";
import { Icon } from "./Icon";
import { resumeHrefFromOrder, useOrder } from "./order";
import { useMoney } from "./useMoney";
import { MoneyBackNote } from "./MoneyBackNote";

/**
 * The Payment step of the PUBLIC configurator (app/configure, flag
 * `growth_guest_configurator`). A guest has seen the real server-computed price and
 * the full configuration; this is the one place an account is asked for.
 *
 * It takes no money and creates nothing. It sends the visitor to the ordinary
 * /register or /login with `?next=` set to the real wizard URL carrying their
 * selection (resumeHrefFromOrder), so they land back on /dashboard/deploy with the
 * same service, game, tier, term, region and add-ons chosen — and the real wizard
 * re-quotes the price with their account (coupons, partner discount, wallet) and
 * runs the normal payment step. Not carried, on purpose: the quoted price (always
 * re-priced server-side), and game configuration values such as server passwords
 * (never put in a URL).
 */
export function GuestGate() {
  const { o, cat, price, pricing, game, plan } = useOrder();
  const money = useMoney();
  const next = encodeURIComponent(resumeHrefFromOrder(o));
  const isGame = o.service === "game";
  const tier = isGame ? game?.tiers.find((t) => t.id === o.gamePlanId) : null;
  const what = isGame
    ? `${game?.name ?? "Game server"}${tier ? ` — ${tier.name}` : ""}`
    : `Cloud VPS${plan ? ` — ${plan.name}` : ""}`;
  const term = cat.terms.find((t) => t.months === o.termMonths)?.label ?? `${o.termMonths} months`;
  const ready = price !== null && !pricing;

  return (
    <div className="card mx-auto flex w-full max-w-[560px] flex-col gap-4 p-5">
      <div className="flex flex-col gap-1">
        <span className="text-[16px] font-extrabold tracking-[-0.02em] text-white">Create your account to pay</span>
        <span className="text-[12.5px] leading-[1.5] text-tx-mute">
          Your selection is saved. After you sign up or log in you will land on the payment step with everything
          below already chosen.
        </span>
      </div>

      <div className="flex flex-col gap-2 rounded-[10px] border border-rim-soft px-3.5 py-3">
        <div className="flex items-baseline justify-between gap-3">
          <span className="trunc text-[13px] font-bold text-white">{what}</span>
          <span className="flex-none text-[11.5px] text-tx-faint">{term}</span>
        </div>
        <div className="flex items-end justify-between gap-3">
          <span className="text-[12px] text-tx-faint">Due today</span>
          <span className={"num text-[24px] text-white transition-opacity " + (pricing ? "opacity-45" : "")}>
            {price ? money(price.totalCents) : "—"}
          </span>
        </div>
        {ready && price.renewalTotalCents > 0 && (
          <span className="text-[11.5px] text-tx-faint">
            Then {money(price.renewalTotalCents)} every {o.termMonths === 1 ? "month" : `${o.termMonths} months`}.
          </span>
        )}
        <span className="text-[11px] leading-snug text-tx-faint">
          List price. Any promo or partner code is applied at checkout once you have an account.
        </span>
      </div>

      <MoneyBackNote />

      <div className="flex flex-col gap-2 sm:flex-row">
        <Link href={`/register?next=${next}`} className="btn-deploy flex-1 justify-center py-3 text-sm">
          <Icon name="lock" size={14} /> Create account
          <span className="dep-arrow">→</span>
        </Link>
        <Link href={`/login?next=${next}`} className="btn-ghost flex h-[46px] flex-1 items-center justify-center px-4 text-[13px]">
          I already have an account
        </Link>
      </div>
      <span className="text-[11px] leading-snug text-tx-faint">
        New accounts confirm their email address before their first purchase.
      </span>
    </div>
  );
}
