 * before signing up. Same data builder as /dashboard/deploy (DeployPageContent), so
 * every number is the one the charge path computes. The Payment step is replaced by
 * the sign-up gate (components/nx/GuestGate.tsx).
 *
 * A signed-in visitor is sent straight to the real wizard with the same query, so a
 * shared /configure link never strands an existing customer. Gated by the layout.
 */
export const dynamic = "force-dynamic";

export default async function ConfigurePage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await currentUser();
  if (user) {
    const sp = await searchParams;
    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(sp)) {
      if (typeof v === "string") qs.set(k, v);
    }
    const s = qs.toString();
    redirect(s ? `/dashboard/deploy?${s}` : "/dashboard/deploy");
  }
  return <DeployPageContent user={null} />;
}
