import { createHash } from "node:crypto";

/**
 * SEA purchasing-power price test (prd-022) — pure rules. DEFAULT OFF
 * (`sea_price_test_enabled`); nothing here runs until an operator turns it on AND
 * names a coupon (`sea_price_test_coupon`).
 *
 * WHAT THE TEST IS. For visitors in South-East/South Asia who pick Singapore, on
 * Minecraft and Valheim only, half are assigned the TEST arm and are offered a lower
 * price; half are the CONTROL arm and see today's list price. The lower price is NOT
 * a new pricing code path: it is a coupon the operator creates in the existing coupon
 * engine (percent off, with whatever first-time/term limits they choose), pre-filled
 * into the wizard's promo field for the test arm. So the discount is shown openly on
 * the order ("<coupon label>"), is charged by the same audited path as any coupon,
 * and the quote and the charge cannot disagree. Nothing about the arm is hidden from
 * the customer or changes after they pay.
 *
 * WHAT IS MEASURED (and what is not). Each time an eligible visitor reaches the
 * game size step, one `DeployFunnelEvent` (type select, step "sea_price_test") records
 * their arm, game and region. scripts/sea-price-test-report.ts then counts, per arm,
 * exposed visitors who were signed in, how many went on to buy a paid game server
 * afterwards, and what they paid. NOT measured: anonymous visitors who never sign up
 * (cannot be tied to an order), traffic quality (the visitor data carries a known bot
 * caveat), and anything about margin or arbitrage (a visitor can use a VPN or type the
 * code). No significance test is run or implied — read the counts, not a verdict.
 * Assignment is by a stable visitor id (cookie, else the account id), so a person
 * sees the same arm every visit; a person whose cookie is cleared may be re-assigned.
 */

export type SeaArm = "test" | "control";

/** South-East Asia + the South Asian markets in the visitor data (ISO alpha-2). */
export const SEA_TEST_COUNTRIES: ReadonlySet<string> = new Set([
  "SG", "MY", "TH", "VN", "ID", "PH", "KH", "LA", "MM", "BN", "TL",
  "IN", "BD", "PK", "LK", "NP",
]);

/** The two games the test runs on. */
export const SEA_TEST_FAMILIES: readonly string[] = ["minecraft", "valheim"];

/** Region the test is limited to (our Singapore datacenter). */
export const SEA_TEST_REGION = "sgp1";

/** Stable 50/50 split on a visitor key. Same key -> same arm, always. */
export function seaTestArm(key: string): SeaArm {
  const h = createHash("sha256").update(`sea-price-test:v1:${key}`).digest();
  return h[0] < 128 ? "test" : "control";
}

export function seaTestCountryEligible(country: string | null | undefined): boolean {
  return SEA_TEST_COUNTRIES.has((country ?? "").trim().toUpperCase());
}

/** The order-level conditions (the visitor-level one is the country). */
export function seaTestOrderEligible(o: { gameFamily: string | null; region: string | null }): boolean {
  return !!o.gameFamily && SEA_TEST_FAMILIES.includes(o.gameFamily) && o.region === SEA_TEST_REGION;
}

/** Coupon codes are matched upper-case everywhere in the wizard. */
export function normaliseSeaCoupon(raw: string | null | undefined): string | null {
  const c = (raw ?? "").trim().toUpperCase();
  return /^[A-Z0-9_-]{3,32}$/.test(c) ? c : null;
}

/** Per-arm roll-up of exposure rows. Pure so it can be tested without a database. */
export type SeaExposure = { subject: string; arm: SeaArm; at: Date };
export type SeaOutcome = { subject: string; at: Date; paidCents: number };
export type SeaArmSummary = { arm: SeaArm; exposed: number; buyers: number; revenueCents: number; revenuePerExposedCents: number | null };

export function summariseSeaTest(exposures: SeaExposure[], outcomes: SeaOutcome[]): SeaArmSummary[] {
  const first = new Map<string, SeaExposure>();
  for (const e of [...exposures].sort((a, b) => a.at.getTime() - b.at.getTime())) {
    if (!first.has(e.subject)) first.set(e.subject, e); // a subject counts once, in the arm first shown
  }
  const out: SeaArmSummary[] = [];
  for (const arm of ["test", "control"] as const) {
    const subjects = [...first.values()].filter((e) => e.arm === arm);
    let buyers = 0;
    let revenue = 0;
    for (const e of subjects) {
      const mine = outcomes.filter((o) => o.subject === e.subject && o.at.getTime() >= e.at.getTime() && o.paidCents > 0);
      if (mine.length > 0) buyers++;
      revenue += mine.reduce((s, o) => s + o.paidCents, 0);
    }
    out.push({
      arm, exposed: subjects.length, buyers, revenueCents: revenue,
      revenuePerExposedCents: subjects.length ? Math.round(revenue / subjects.length) : null,
    });
  }
  return out;
}
