cat > scripts/sea-price-test-report.ts <<'E'
/**
 * READ-ONLY report for the SEA price test (prd-022). Prints per-arm counts from
 * DeployFunnelEvent exposures and real paid game orders. Writes nothing.
 *
 *   npx tsx scripts/sea-price-test-report.ts [days=30]
 *
 * Read lib/sea-price-test.ts first for what this does NOT measure (anonymous visitors,
 * traffic quality, margin, VPN/arbitrage). It prints counts and revenue per exposed
 * visitor; it deliberately computes no p-value and draws no conclusion.
 */
import { db } from "../lib/db";
import { summariseSeaTest, SEA_TEST_FAMILIES, type SeaExposure, type SeaOutcome } from "../lib/sea-price-test";

async function main() {
  const days = Math.max(1, Math.min(365, Number(process.argv[2]) || 30));
  const since = new Date(Date.now() - days * 86_400_000);

  // `detail` is not in the generated client (see the DeployFunnelEvent comment), hence raw SQL.
  const rows = await db.$queryRaw<{ userId: string | null; detail: string | null; createdAt: Date }[]>`
    SELECT "userId", "detail", "createdAt" FROM "DeployFunnelEvent"
    WHERE "type" = 'select' AND "step" = 'sea_price_test' AND "createdAt" >= ${since}`;
  const exposures: SeaExposure[] = [];
  for (const r of rows) {
    if (!r.userId || !r.detail) continue; // anonymous exposures cannot be tied to an order
    try {
      const d = JSON.parse(r.detail) as { value?: string };
      if (d.value === "test" || d.value === "control") exposures.push({ subject: r.userId, arm: d.value, at: r.createdAt });
    } catch { /* skip unreadable */ }
  }
  const anon = rows.filter((r) => !r.userId).length;
  const subjects = [...new Set(exposures.map((e) => e.subject))];

  const outcomes: SeaOutcome[] = [];
  if (subjects.length) {
    const servers = await db.server.findMany({
      where: { userId: { in: subjects }, isFree: false, createdAt: { gte: since }, osTemplate: { family: { in: [...SEA_TEST_FAMILIES] } } },
      select: { userId: true, createdAt: true },
    });
    const invoices = await db.invoice.findMany({
      where: { userId: { in: subjects }, status: "PAID", createdAt: { gte: since } },
      select: { userId: true, createdAt: true, amountCents: true, description: true },
    });
    const buyers = new Set(servers.map((s) => s.userId));
    for (const inv of invoices) {
      // Only users who really bought a test-family server; wallet top-ups are not revenue.
      if (!buyers.has(inv.userId) || /wallet top-up/i.test(inv.description ?? "")) continue;
      outcomes.push({ subject: inv.userId, at: inv.createdAt, paidCents: inv.amountCents });
    }
  }

  const out = summariseSeaTest(exposures, outcomes);
  console.log(`SEA price test, last ${days} days. Signed-in exposures only (${anon} anonymous exposure rows ignored).`);
  for (const a of out) {
    console.log(`${a.arm.padEnd(8)} exposed=${a.exposed} buyers=${a.buyers} revenue=$${(a.revenueCents / 100).toFixed(2)} perExposed=${a.revenuePerExposedCents === null ? "n/a" : "$" + (a.revenuePerExposedCents / 100).toFixed(2)}`);
  }
  console.log("Counts only. No significance test. Not measured: anonymous visitors, bot share, margin, VPN/arbitrage.");
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());
