  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: none, bufferPct: 2 }), null);
  assert.equal(localChargeCents({ usdCents: 1000, method: "upi", rates: none, bufferPct: 2 }), null);
  assert.equal(localChargeCents({ usdCents: 1000, method: "alipay", rates: none, bufferPct: 2 }), 1000);
  assert.equal(localChargeCents({ usdCents: 1000, method: "wechat_pay", rates: none, bufferPct: 5 }), 1000, "no buffer on a USD charge");
});

test("local charge = usd x rate x (1+buffer), rounded UP, never short", () => {
  const r = parseLocalFxRates('{"SGD":1.3,"INR":83}');
  // 1000c * 1.3 = 1300 exactly; +2% = 1326
  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: r, bufferPct: 2 }), 1326);
  // zero buffer, float-noise case: 1.3 * 100 must not round up to 131
  assert.equal(localChargeCents({ usdCents: 100, method: "paynow", rates: r, bufferPct: 0 }), 130);
  // fractional result rounds up: 501c * 83 = 41583 (+0%)
  assert.equal(localChargeCents({ usdCents: 501, method: "upi", rates: r, bufferPct: 0 }), 41583);
  assert.equal(localChargeCents({ usdCents: 1, method: "paynow", rates: r, bufferPct: 0 }), 2, "1c*1.3=1.3 -> 2");
  // buffer is clamped to 0..20
  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: r, bufferPct: 500 }), 1560);
  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: r, bufferPct: -50 }), 1300);
});

