import test from "node:test";
import assert from "node:assert/strict";
import {
  LOCAL_METHODS, localChargeCents, methodSupportedByEntity, parseLocalFxRates, walletCreditCents, isLocalMethodId,
} from "../lib/local-payment-methods";

test("a method is only supported by the Stripe account countries Stripe allows it for", () => {
  assert.equal(methodSupportedByEntity("paynow", "SG"), true);
  assert.equal(methodSupportedByEntity("paynow", "CA"), false);
  assert.equal(methodSupportedByEntity("grabpay", "sg"), true);
  assert.equal(methodSupportedByEntity("upi", "CA"), true);
  assert.equal(methodSupportedByEntity("upi", "SG"), true);
  assert.equal(methodSupportedByEntity("alipay", "CA"), true);
  assert.equal(methodSupportedByEntity("wechat_pay", "SG"), false);
});

test("an unknown or blank entity country offers nothing", () => {
  for (const id of Object.keys(LOCAL_METHODS) as (keyof typeof LOCAL_METHODS)[]) {
    assert.equal(methodSupportedByEntity(id, ""), false);
    assert.equal(methodSupportedByEntity(id, null), false);
    assert.equal(methodSupportedByEntity(id, "SGP"), false);
  }
});

test("GCash, QRIS and friends are not method ids", () => {
  for (const bad of ["gcash", "qris", "maya", "card", "", "__proto__", "toString"]) assert.equal(isLocalMethodId(bad), false);
});

test("FX rate parsing drops anything malformed and never invents a rate", () => {
  assert.deepEqual(parseLocalFxRates(undefined), { USD: 1 });
  assert.deepEqual(parseLocalFxRates("not json"), { USD: 1 });
  assert.deepEqual(parseLocalFxRates("[1,2]"), { USD: 1 });
  assert.deepEqual(parseLocalFxRates('{"SGD":"1.3","INR":83,"XX":2,"EUR":-1,"GBP":0,"JPY":"abc"}'), { USD: 1, SGD: 1.3, INR: 83 });
  // USD can never be overridden.
  assert.equal(parseLocalFxRates('{"USD":5}').USD, 1);
});

test("SGD/INR methods cannot be priced without a rate; USD methods need none", () => {
  const none = parseLocalFxRates("{}");
  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: none, bufferPct: 2 }), null);
  assert.equal(localChargeCents({ usdCents: 1000, method: "upi", rates: none, bufferPct: 2 }), null);
  assert.equal(localChargeCents({ usdCents: 1000, method: "alipay", rates: none, bufferPct: 2 }), 1000);
  assert.equal(localChargeCents({ usdCents: 1000, method: "wechat_pay", rates: none, bufferPct: 5 }), 1000, "no buffer on a USD charge");
});

test("local charge = usd x rate x (1+buffer), rounded UP, never short", () => {
  const r = parseLocalFxRates('{"SGD":1.3,"INR":83}');
  // 1000c * 1.3 = 1300 exactly; +2% = 1326
  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: r, bufferPct: 2 }), 1326);
  // zero buffer, float-noise case: 1.3 * 100 must not round up to 131
  assert.equal(localChargeCents({ usdCents: 100, method: "paynow", rates: r, bufferPct: 0 }), 130);
  // fractional result rounds up: 501c * 83 = 41583 (+0%)
  assert.equal(localChargeCents({ usdCents: 501, method: "upi", rates: r, bufferPct: 0 }), 41583);
  assert.equal(localChargeCents({ usdCents: 1, method: "paynow", rates: r, bufferPct: 0 }), 2, "1c*1.3=1.3 -> 2");
  // buffer is clamped to 0..20
  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: r, bufferPct: 500 }), 1560);
  assert.equal(localChargeCents({ usdCents: 1000, method: "paynow", rates: r, bufferPct: -50 }), 1300);
});

test("bad amounts are refused", () => {
  const r = parseLocalFxRates('{"SGD":1.3}');
  for (const usdCents of [0, -5, 1.5, NaN]) {
    assert.equal(localChargeCents({ usdCents, method: "paynow", rates: r, bufferPct: 0 }), null);
  }
});

