  assert.equal(walletCreditCents({ amount_total: 2500, currency: null, metadata: null }), 2500, "legacy session without currency is USD");
  assert.equal(walletCreditCents({ amount_total: 0, currency: "usd" }), 0);
  assert.equal(walletCreditCents({ amount_total: null, currency: "usd" }), 0);
});

test("walletCreditCents: a non-USD session without the local marker credits NOTHING (no foreign cents as dollars)", () => {
  assert.equal(walletCreditCents({ amount_total: 1326, currency: "sgd", metadata: { nxeonUserId: "u" } }), 0);
  assert.equal(walletCreditCents({ amount_total: 83000, currency: "inr", metadata: {} }), 0);
});

test("walletCreditCents: a local session credits the USD it was priced for, not the SGD charged", () => {
  const m = { nxeonUserId: "u", nxeonLocalPay: "paynow", nxeonCreditUsdCents: "1000" };
  assert.equal(walletCreditCents({ amount_total: 1326, currency: "sgd", metadata: m }), 1000);
});

test("walletCreditCents: refuses tampered / inconsistent local sessions", () => {
  const base = { nxeonUserId: "u", nxeonLocalPay: "paynow", nxeonCreditUsdCents: "1000" };
  assert.equal(walletCreditCents({ amount_total: 1326, currency: "usd", metadata: base }), 0, "paynow must be SGD");
  assert.equal(walletCreditCents({ amount_total: 1326, currency: "inr", metadata: base }), 0);
  assert.equal(walletCreditCents({ amount_total: 1326, currency: "sgd", metadata: { ...base, nxeonLocalPay: "gcash" } }), 0, "unknown method");
  for (const bad of ["", "0", "-5", "10.5", "abc", "1e3x"]) {
    assert.equal(walletCreditCents({ amount_total: 1326, currency: "sgd", metadata: { ...base, nxeonCreditUsdCents: bad } }), 0, `credit "${bad}"`);
  }
  // A USD-charged local method (alipay) must credit exactly what it charged.
  const ali = { nxeonUserId: "u", nxeonLocalPay: "alipay", nxeonCreditUsdCents: "1000" };
  assert.equal(walletCreditCents({ amount_total: 1000, currency: "usd", metadata: ali }), 1000);
  assert.equal(walletCreditCents({ amount_total: 500, currency: "usd", metadata: ali }), 0, "credit may not exceed the charge");
});

test("every local method's charge currency is one we can price or is USD", () => {
  for (const m of Object.values(LOCAL_METHODS)) assert.match(m.chargeCurrency, /^[A-Z]{3}$/);
});
