#!/bin/bash
# usage: run.sh <outdir> <routes,comma> [modes]
# Starts ONE next dev on :3187 in the adminpages worktree, runs smoke.mjs, kills it by PID/port.
set -u
D=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/adminpages
cd /opt/nxeon-wt-adminpages || exit 1
PORT=3187 npx next dev -p 3187 > $D/dev.log 2>&1 &
DEV=$!
for i in $(seq 1 150); do curl -s -o /dev/null http://127.0.0.1:3187/api/health && break; sleep 2; done
export USER_ID=$(PGPASSWORD=agtadminpages psql -h localhost -U agt_adminpages nxeon_agt_adminpages -At -c "select id from \"User\" where email='admin@nxeon.local'")
curl -s -o /dev/null -m 400 http://127.0.0.1:3187/admin/login
node $D/smoke.mjs "http://localhost:3187" "$1" "$2" "${3:-desktop-dark,mobile-dark}"
kill $DEV 2>/dev/null; sleep 2; kill -9 $DEV 2>/dev/null
P=$(ss -ltnp 'sport = :3187' | grep -oP 'pid=\K[0-9]+' | sort -u); [ -n "$P" ] && kill $P
true
model GamePlan {
  id           String   @id @default(cuid())
  gameFamily   String // minecraft, valheim, rust, palworld, cs2, terraria, ...
  name         String // e.g. "Minecraft — 4 GB / 20 slots"
  ramMB        Int
  cpuCores     Int      @default(2)
  diskGB       Int
  slots        Int? // player slots (nullable)
  priceCents   Int // retail price the customer pays (per term) — the REGULAR/renewal rate
  introPriceCents Int?
  introTermMonths Int?
  termMonths   Int      @default(1)
  basePlanId   String // the VPS Plan used to size/provision the VM
  basePlan     Plan     @relation(fields: [basePlanId], references: [id])
  osTemplateId String? // the game's OsTemplate (image) to deploy
  featured     Boolean  @default(false)
  active       Boolean  @default(true)
  sortOrder    Int      @default(0)
  createdAt    DateTime @default(now())
  servers      Server[]
}
model Node {
  id               String        @id @default(cuid())
  name             String        @unique
  pveNode          String // Proxmox node name (e.g. ns5002569)
  apiUrl           String // https://host:8006
  tokenId          String
  tokenSecret      String
  publicIp         String
  bridge           String        @default("vmbr1")
  subnetPrefix     String        @default("10.20.0.") // /24 NAT subnet prefix
  ipStart          Int           @default(100)
  ipEnd            Int           @default(250)
  sshPortStart     Int           @default(20000)
  sshPortEnd       Int           @default(29999)
  natChain         String        @default("NXEON_FWD")
  storageNvme      String        @default("vmdata")
  storageHdd       String        @default("vmdata-hdd")
  capacityRamMB    Int           @default(56000)
  monthlyCostCents Int?
  isPrimary        Boolean       @default(false)
  enabled          Boolean       @default(true)
  status           NodeStatus    @default(ONLINE)
  provider         NodeProvider  @default(OVH)
  region           String        @default("sgp1")
  providerServerId String?
  agentTokenEnc    String?
  agentPort        Int           @default(8943)
  lastSeenAt       DateTime?
  createdAt        DateTime      @default(now())
  servers          Server[]
  dedicatedIps     DedicatedIp[]

  acceptsProvisions Boolean       @default(true)
}
model OsTemplate {
  id              String        @id @default(cuid())
  slug            String        @unique
  name            String // display name, e.g. "Ubuntu"
  category        ImageCategory @default(PLAIN_OS)
  family          String        @default("linux") // ubuntu | debian | almalinux | rocky | cpanel | ...
  version         String        @default("") // "24.04", "13", ""
  logo            String        @default("") // icon slug for the UI
  vmid            Int // legacy/base template VMID to clone
  baseVmid        Int? // explicit base OS template for panels/apps (falls back to vmid)
  setupScript     String? // shell installed via cloud-init runcmd (panels/apps)
  minRamMB        Int           @default(1024)
  minDiskGB       Int           @default(10)
  licenseRequired Boolean       @default(false) // e.g. cPanel/Plesk need a paid license
  featured        Boolean       @default(false)
  sortOrder       Int           @default(0)
  active          Boolean       @default(true)
  servers         Server[]
}

test("payAndDeploy hands its own quote to checkout instead of letting it re-quote", () => {
  const actions = code("../lib/actions.ts");
  assert.match(
    actions,
    /createOrderCheckout\(user, cardCents, intent, orderPriceOf\(quote\)\)/,
    "the wallet split and the stamped total must come from ONE quote — two `new Date()` calls " +
      "straddling a promo boundary would price the card leg and the total against different worlds"
  );
});

/* ------------------------------------------------------------------ *
 * The receipt promised an attachment it never sent
 * ------------------------------------------------------------------ */

test("the receipt only claims an attached invoice when one is attached", async () => {
  const { emails } = await import("../lib/email-templates.ts");
  const withFile = emails.receipt("$67.96", "your Nxeon order", true);
  assert.match(withFile.html, /attached for your records/);

  const withoutFile = emails.receipt("$67.96", "your Nxeon order", false);
  assert.ok(
    !/attached/i.test(withoutFile.html),
    "a receipt with no attachment must not tell the customer to look for one"
  );
